"""Generate the M1 contract fixtures (schemas, samples, recordings) into tests/contracts."""

import json
import sys
from pathlib import Path

OUT = Path(sys.argv[1])


def write(folder, rel, data):
    path = OUT / folder / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=1) + "\n")


# ------------------------------------------------------------------ schemas
NUM = {"type": "number"}
INT = {"type": "integer"}
NAT = {"type": "integer", "minimum": 0}
POS = {"type": "integer", "minimum": 1}
STR = {"type": "string"}
BOOL = {"type": "boolean"}
P = {"type": "number", "minimum": 0, "maximum": 1}
DIRECTION = {"enum": ["higher", "lower"]}


def obj(props):
    return {
        "type": "object",
        "properties": props,
        "required": list(props),
        "additionalProperties": False,
    }


def arr(items, n=None):
    d = {"type": "array", "items": items}
    if n is not None:
        d["minItems"] = d["maxItems"] = n
    return d


def ref(name):
    return {"$ref": f"#/$defs/{name}"}


def nullable(s):
    return {"anyOf": [s, {"type": "null"}]}


def mapping(values):
    return {"type": "object", "additionalProperties": values}


DEFS = {
