def refs(node, found):
    if isinstance(node, dict):
        if "$ref" in node:
            name = node["$ref"].rsplit("/", 1)[1]
            if name not in found:
                found.add(name)
                refs(DEFS[name], found)
        for value in node.values():
            refs(value, found)
    elif isinstance(node, list):
        for value in node:
            refs(value, found)


def schema(folder, type_name):
    found = {type_name}
    refs(DEFS[type_name], found)
    write(
        folder,
        "schema.json",
        {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": folder,
            "$ref": f"#/$defs/{type_name}",
            "$defs": {name: DEFS[name] for name in sorted(found)},
        },
    )


