# ------------------------------------------------------------------ snake simulation
HEADINGS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # up, right, down, left


def blocked(cell, body):
    x, y = cell
    return not (0 <= x < 10 and 0 <= y < 10) or cell in body[:-1]


def snake_obs(body, heading, food):
    head = body[0]

    def danger(h):
        dx, dy = HEADINGS[h % 4]
        return float(blocked((head[0] + dx, head[1] + dy), body))

    fx, fy = food[0] - head[0], food[1] - head[1]
    return [
        danger(heading),
        danger(heading - 1),
        danger(heading + 1),
        *[float(i == heading) for i in range(4)],
        float(fy < 0),
        float(fx > 0),
        float(fy > 0),
        float(fx < 0),
        float(len(body)),
    ]


def snake_draw(body, food):
    objects = [
        {"kind": "snake-head", "x": float(body[0][0]), "y": float(body[0][1]), "size": 1.0,
         "team": "snake", "agent": 0}
    ]
    objects += [
        {"kind": "snake-body", "x": float(x), "y": float(y), "size": 1.0, "team": "snake",
         "agent": None}
        for x, y in body[1:]
    ]
    objects.append(
        {"kind": "food", "x": float(food[0]), "y": float(food[1]), "size": 1.0, "team": None,
         "agent": None}
    )
    return {"width": 10.0, "height": 10.0, "objects": objects}


def snake_episode(seed, body, heading, foods, actions, max_steps):
    """Index i: the Step, DrawState and running EpisodeResult after i steps."""
    foods = list(foods)
    food = foods.pop(0)
    eaten, total = 0, 0.0
    out = []

    def record(actions_taken, reward, done, truncated, length):
        out.append(
            {
                "actions": actions_taken,
                "step": {
                    "obs": [snake_obs(body, heading, food)],
                    "rewards": [reward],
                    "active": [True],
                    "done": done,
                    "truncated": truncated,
                },
                "draw": snake_draw(body, food),
                "result": {
                    "seed": seed,
                    "length": length,
                    "scores": {"snake": float(eaten)},
                    "team_rewards": {"snake": total},
                    "measures": {},
                },
            }
        )

    record(None, 0.0, False, False, 0)
    for i, action in enumerate(actions, start=1):
        heading = (heading + {0: 0, 1: -1, 2: 1}[action]) % 4
        dx, dy = HEADINGS[heading]
        head = (body[0][0] + dx, body[0][1] + dy)
        assert not blocked(head, body)
        body.insert(0, head)
        reward = 0.0
        if head == food:
            eaten += 1
            reward = 1.0
            food = foods.pop(0)
        else:
            body.pop()
        total += reward
        truncated = i == max_steps
        record([action], reward, truncated, truncated, i)
    return out


EP42 = snake_episode(42, [(5, 5), (5, 6), (5, 7)], 0, [(8, 4), (2, 7)], [0, 2, 0, 0, 2], 5)
EP7 = snake_episode(7, [(5, 5), (5, 6), (5, 7)], 0, [(5, 3), (1, 1)], [0, 0, 0], 3)


def frames(episode):
    return [
        {
            "step": i,
            "draw": entry["draw"],
            "scores": entry["result"]["scores"],
            "rewards": entry["step"]["rewards"],
        }
        for i, entry in enumerate(episode)
    ]


# ------------------------------------------------------------------ check worlds
def corridor_episode(seed, start, actions):
    out = []
    state, total = start, 0.0

    def draw(s):
        return {
            "width": 8.0,
            "height": 1.0,
            "objects": [
                {"kind": "exit", "x": 0.0, "y": 0.0, "size": 1.0, "team": None, "agent": None},
                {"kind": "exit", "x": 7.0, "y": 0.0, "size": 1.0, "team": None, "agent": None},
                {"kind": "agent", "x": float(s + 1), "y": 0.0, "size": 1.0, "team": "agent",
                 "agent": 0},
            ],
        }

    def entry(actions_taken, reward, done, length, s):
        obs = [float(i == s) for i in range(6)] if 0 <= s <= 5 else [0.0] * 6
        return {
            "actions": actions_taken,
            "step": {"obs": [obs], "rewards": [reward], "active": [True], "done": done,
                     "truncated": False},
            "draw": draw(s),
            "result": {"seed": seed, "length": length, "scores": {"agent": total},
                       "team_rewards": {"agent": total}, "measures": {}},
        }

    out.append(entry(None, 0.0, False, 0, state))
    for i, action in enumerate(actions, start=1):
        state += 1 if action == 1 else -1
        reward = 1.0 if state == 6 else 0.8 if state == -1 else 0.0
        total += reward
        out.append(entry([action], reward, state in (-1, 6), i, state))
    return out


CORRIDOR = corridor_episode(0, 2, [1, 1, 1, 1])
CORRIDOR3 = corridor_episode(1, 3, [1, 1, 1])


def point_episode(seed, start, pushes):
    out = []
    x, total = start, 0.0

    def entry(actions_taken, reward, done, length):
        return {
            "actions": actions_taken,
            "step": {"obs": [[x]], "rewards": [reward], "active": [True], "done": done,
                     "truncated": False},
            "draw": {"width": 2.0, "height": 1.0, "objects": [
                {"kind": "target", "x": 1.0, "y": 0.5, "size": 0.1, "team": None, "agent": None},
                {"kind": "agent", "x": round(x + 1.0, 6), "y": 0.5, "size": 0.1,
                 "team": "agent", "agent": 0},
            ]},
            "result": {"seed": seed, "length": length, "scores": {"agent": total},
                       "team_rewards": {"agent": total}, "measures": {}},
        }

    out.append(entry(None, 0.0, False, 0))
    for i, push in enumerate(pushes, start=1):
        x = round(x + 0.2 * push, 6)
        reward = round(-abs(x), 6)
        total = round(total + reward, 6)
        out.append(entry([[float(push)]], reward, abs(x) < 0.05, i))
    return out


