# ------------------------------------------------------------------ runs
def run_folder(name):
    return f"runs/snake/default/{name}"


def eval_points(seed):
    points = []
    for k in range(21):
        step = 100 * k
        points.append(
            {"step": step, "scores": {"snake": round((8 + 0.3 * seed) * k / 20, 4)},
             "measures": {}}
        )
    return points


def episodes(seed):
    lengths = [37, 52, 61, 88, 140, 212]
    return [
        {"seed": 1000 * seed + i, "length": n, "scores": {"snake": float(i + seed // 2)},
         "team_rewards": {"snake": float(i + seed // 2) - 1.0}, "measures": {}}
        for i, n in enumerate(lengths)
    ]


def checkpoint(name, pct, budget, spec=None):
    return {
        "run": name,
        "pct": pct,
        "step": budget * pct // 100,
        "spec": spec or snake_spec(),
        "methods": {"snake": DQN},
        "state": {"snake": {"observed": budget * pct // 100}},
        "path": f"{run_folder(name)}/checkpoints/ckpt_{pct}.pt",
    }


def record(seed, status, ended, failure=None, budget=2000):
    name = f"snake-default-s{seed}"
    return {
        "config": snake_config(seed, budget),
        "spec": snake_spec(),
        "started": "2026-10-17T09:00:00+00:00",
        "ended": ended,
        "status": status,
        "failure": failure,
        "path": run_folder(name),
    }


def run_recording(seed, status="finished"):
    name = f"snake-default-s{seed}"
    finished = status == "finished"
    evals = eval_points(seed) if finished else eval_points(seed)[:8]
    pcts = [0, 50, 100] if finished else [0]
    return {
        "record": record(seed, status, "2026-10-17T09:41:00+00:00" if finished else None),
        "episodes": episodes(seed) if finished else episodes(seed)[:2],
        "evals": evals,
        "checkpoints": [checkpoint(name, pct, 2000) for pct in pcts],
    }


