def fish_obs(i, seen):
    base = [round(1.0 + 0.7 * i, 2), round(2.0 + 0.3 * i, 2), 0.1 * (i % 3), -0.05 * i]
    ball = [1.0, round(0.5 - 0.1 * i, 2), 0.25, 0.4, -0.3] if seen else [0.0] * 5
    return [base + ball]


