SHORT = {"epsilon_decay_steps": 500}


def run_data(s: int, incomplete_at: int | None = None) -> dict[str, Any]:
    r = np.random.default_rng(100 + s)
    cfg = core.RunConfig(f"snake-default-s{s}", "snake", "default", {"snake": DQN}, s, 2000, {"dqn": SHORT})
    end = incomplete_at or 2000
    path = Path(f"runs/snake/default/snake-default-s{s}")
    eps, t, seed = [], 0, s * 1_000
    while True:
        length = int(r.integers(30, 150))
        if t + length > end:
            break
        t += length
        food = int(r.binomial(10, min(0.9, t / 2600)))
        eps.append((t, core.EpisodeResult(seed + len(eps), length, {"snake": float(food)}, {"snake": float(food)}, {})))
    evals = [(step, runlog.EvalPoint(step, {"snake": round(max(0.0, 8 * step / 2000 * (0.85 + 0.05 * s) + float(r.normal(0, 0.3))), 3)}, {})) for step in range(0, end + 1, 100)]
    ckpts = []
    for pct in (0, 50, 100):
        step_ = pct * 20
        if step_ > end:
            continue
        st = {"snake": {"q.0.weight": np.round(r.normal(0, 0.3, (2, 10)), 4).tolist(), "q.0.bias": [0.0, 0.0], "q.2.weight": np.round(r.normal(0, 0.3, (3, 2)), 4).tolist(), "q.2.bias": [0.0, 0.0, 0.0]}}
        ckpts.append((step_, runlog.Checkpoint(cfg.name, pct, step_, SNAKE, {"snake": DQN}, st, path / "checkpoints" / f"ckpt_{pct:03d}.pt")))
    record = runlog.RunRecord(
        cfg, SNAKE, datetime(2026, 10, 18, 9, s, 0),
        None if incomplete_at else datetime(2026, 10, 18, 9, s + 4, 10),
        "incomplete" if incomplete_at else "finished", None, path,
    )
    return {"record": record, "episodes": eps, "evals": evals, "checkpoints": ckpts}


