def summary(names: tuple[str, ...], means: list[float], comps: tuple[evaluate.Comparison, ...], verdict: evaluate.Verdict) -> evaluate.Summary:
    lm = round(sum(means) / len(means), 6)
    return evaluate.Summary("snake", "default", "snake", names, lm, (min(means), max(means)), dict(zip(names, means)), 0.21, 6.3, comps, verdict, None)


